impl PgAmop {
    /// The built-in row whose `oid` is `oid`.
    pub fn by_oid(oid: Oid) -> Option<&'static PgAmop> {
        let position = PG_AMOP.binary_search_by_key(&oid, |row| row.oid).ok()?;
        Some(&PG_AMOP[position])
    }
}

