impl PgOpclass {
    /// The built-in row whose `oid` is `oid`.
    pub fn by_oid(oid: Oid) -> Option<&'static PgOpclass> {
        let position = PG_OPCLASS.binary_search_by_key(&oid, |row| row.oid).ok()?;
        Some(&PG_OPCLASS[position])
    }
}

